sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
     // extra check for amend -- added as part of MSSCUSTODY-6538

    var utils = new MSS_Custody_Event_Utils();
    var evalAmend = utils.evalAmendCase(current.trade_id);

    if (!evalAmend) {
        var custodyCase = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_case");
        custodyCase.initialize();
        custodyCase.short_description = "Investigate " + current.core_stage_reference.status;
        custodyCase.description = "This case is created when a  " + current.core_stage_reference.status + " status is received. This case will remain open until a new trade lifecycle status is received.";
        custodyCase.triggered_by = current.core_stage_reference; // Populating Triggered by in Custody case - MSSCUSTODY-705
        custodyCase.u_fo_process_status = current.core_stage_reference;
        custodyCase.u_object_type = current.object_type;
        custodyCase.trade_id = current.trade_id;
        var bpiValue = current.number;
        custodyCase.u_business_process_instance = current.sys_id;
        custodyCase.u_source = current.source_system;
        var newobjectid = custodyCase.insert();
        current.is_case_created_core = true;
		gs.info('In Line 21');
        current.case_counter++;
		gs.info('In Line 23'+current.number);


        //3733/3732 before the case type change to auto
        new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().updateAutomatedManulTask(current.trade_id, newobjectid);

        new x_hsb11_mss_c_proc.MSSCustodyBulkUtils().setTradeCaseType(current.trade_id, 'automated'); // MSSCUSTODY-3326 - To set case type value to Automated


    }

})(current, previous);
